SELECT 
FROM orchestrator_runs
WHERE case_id = #{caseId}
  AND trigger_type = #{triggerType}
  AND trigger_key = #{triggerKey}

SELECT COUNT(*)
FROM orchestrator_runs
WHERE case_id = #{caseId}

